function Get-GitBlobBytes([string]$repo,[string]$spec){
  $psi = New-Object System.Diagnostics.ProcessStartInfo
  $psi.FileName = 'git'; $psi.Arguments = "-C `"$repo`" cat-file blob $spec"
  $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true; $psi.UseShellExecute = $false
  $p = [System.Diagnostics.Process]::Start($psi)
  $ms = New-Object System.IO.MemoryStream
  $p.StandardOutput.BaseStream.CopyTo($ms); $p.WaitForExit()
  return $ms.ToArray()
}

$blob = Get-GitBlobBytes $repo "test1`:$rel"
$work = [System.IO.File]::ReadAllBytes("$repo\$rel")
Write-Output ("blob bytes = {0} ; work bytes = {1}" -f $blob.Length, $work.Length)

function Stat([byte[]]$b,[string]$tag){
  $cr=0;$lf=0;$crlf=0;$nul=0;$lonecr=0
  for($i=0;$i -lt $b.Length;$i++){
    if($b[$i] -eq 13){ if($i+1 -lt $b.Length -and $b[$i+1] -eq 10){$crlf++} else {$lonecr++} }
    elseif($b[$i] -eq 10){$lf++}
    elseif($b[$i] -eq 0){$nul++}
  }
  Write-Output ("{0}: CR_total={1} CRLF={2} loneCR={3} LF_total={4} NUL={5}" -f $tag,($cr),$crlf,$loneCR,$lf,$nul)
}
Stat $blob "BLOB"
Stat $work "WORK"
Write-Output "--- last 16 bytes hex (BLOB) ---"
($blob[($blob.Length-16)..($blob.Length-1)] | ForEach-Object { $_.ToString('X2') }) -join ' '
Write-Output "--- last 16 bytes hex (WORK) ---"
($work[($work.Length-16)..($work.Length-1)] | ForEach-Object { $_.ToString('X2') }) -join ' '","description":"Raw byte comparison of blob vs working tree"}

